"""Kitchen Sink page: SvgImage (an SVG, sharp at any size), MediaPlayer (sound and video,
with its bar of controls) and PdfViewer (a PDF the Printer just made: Printer.OutputFile,
then the viewer shows it; Find highlights text in it)."""

import os
import tempfile

from vp6 import *

PDF = os.path.join(tempfile.gettempdir(), "vp6-kitchen-sink.pdf")


class pgMedia(Form):
    # region VP6 Designer - generated by the form designer, do not edit
    def InitializeComponent(self):
        self.Caption = 'Media, SVG and PDF'
        self.Width = 640
        self.Height = 440
        self.svgLogo = SvgImage(self, Left=16, Top=16, Width=180, Height=120, Picture='vp6.svg',
                                ToolTipText='An SvgImage: click it to keep its shape or fill the control')
        self.lblSvg = Label(self, Caption='KeepAspect: the picture keeps its shape', Left=16,
                            Top=140, Width=180, Height=40, WordWrap=True, TabIndex=1)
        self.mpTone = MediaPlayer(self, Left=210, Top=16, Width=230, Height=164,
                                  FileName='tone.wav',
                                  ToolTipText='A MediaPlayer playing a sound (its bar: play, pause, the position)')
        self.cmdPlay = CommandButton(self, Caption='P&lay', Left=210, Top=188, Width=110,
                                     Height=32, TabIndex=2)
        self.cmdStop = CommandButton(self, Caption='S&top', Left=330, Top=188, Width=110,
                                     Height=32, TabIndex=3)
        self.lblMedia = Label(self, Caption='', Left=16, Top=228, Width=424, Height=22, TabIndex=4)
        self.cmdPrintPdf = CommandButton(self, Caption='&Print a PDF and view it', Left=16,
                                         Top=264, Width=210, Height=32, TabIndex=5,
                                         ToolTipText='Printer.OutputFile: the pages go to a PDF, then PdfViewer shows it')
        self.txtFind = TextBox(self, Text='kangaroo', Left=16, Top=308, Width=140, Height=25,
                               TabIndex=6)
        self.cmdFind = CommandButton(self, Caption='&Find', Left=164, Top=304, Width=62, Height=32,
                                     TabIndex=7)
        self.lblPdf = Label(self, Caption='', Left=16, Top=344, Width=424, Height=60,
                            WordWrap=True, TabIndex=8)
        self.pdfDoc = PdfViewer(self, Left=452, Top=16, Width=172, Height=408, PageMode=0,
                                TabIndex=9, ToolTipText='A PdfViewer, one page at a time')
    # endregion

    # --- SvgImage -------------------------------------------------------------------
    def svgLogo_Click(self):
        self.svgLogo.KeepAspect = not self.svgLogo.KeepAspect
        self.lblSvg.Caption = ("KeepAspect: the picture keeps its shape" if self.svgLogo.KeepAspect
                               else "Stretched to fill the control, still sharp")

    # --- MediaPlayer ------------------------------------------------------------------
    def cmdPlay_Click(self):
        self.mpTone.Play()

    def cmdStop_Click(self):
        self.mpTone.Stop()

    def mpTone_StateChange(self):
        state = {vpMediaStopped: "stopped", vpMediaPlaying: "playing",
                 vpMediaPaused: "paused"}[self.mpTone.State]
        self.lblMedia.Caption = f"StateChange: {state} ({self.mpTone.Duration:.1f} s long)"

    def mpTone_Done(self):
        self.lblMedia.Caption = "Done: it played to the end"

    def mpTone_Error(self, Description):
        self.lblMedia.Caption = f"Error: {Description}"

    # --- PdfViewer -------------------------------------------------------------------
    def cmdPrintPdf_Click(self):
        Printer.OutputFile = PDF  # (the pages go to this PDF file)
        try:
            Printer.FontSize = 24
            Printer.Print("The Kitchen Sink's PDF")
            Printer.FontSize = 12
            Printer.Print("Printed with the Printer object, viewed with a PdfViewer.")
            Printer.NewPage()
            Printer.Print("Page two: Find looks for a kangaroo here.")
            Printer.EndDoc()
        finally:
            Printer.OutputFile = ""
        self.pdfDoc.FileName = PDF
        self.lblPdf.Caption = f"{self.pdfDoc.PageCount} pages printed to {PDF}"

    def cmdFind_Click(self):
        if not self.pdfDoc.PageCount:
            self.cmdPrintPdf_Click()
        if self.pdfDoc.Find(self.txtFind.Text):
            self.lblPdf.Caption = f"Found {self.pdfDoc.SelectedText!r} on page {self.pdfDoc.Page}"
        else:
            self.lblPdf.Caption = f"No {self.txtFind.Text!r} in the PDF"

    def pdfDoc_PageChange(self):
        self.lblPdf.Caption = f"PageChange: page {self.pdfDoc.Page} of {self.pdfDoc.PageCount}"


if __name__ == "__main__":
    run(pgMedia)
